#[derive(Clone, Debug, PartialEq)]
pub enum NumpyScalarType {
    Int64,
    Float64,
    Complex128,
    String,
    Bool,
}

#[derive(Clone, Debug)]
pub enum NumpyObject {
    Int(i64),
    Float(f64),
    IntArray(Vec<i64>),
    FloatArray(Vec<f64>),
    ComplexArray(Vec<(f64, f64)>),
    Str(String),
    Bool(bool),
    Generic,
}

pub fn obj2sctype(
    rep: NumpyObject,
    default: Option<NumpyScalarType>,
) -> Option<NumpyScalarType> {
    match rep {
        NumpyObject::Int(_) | NumpyObject::IntArray(_) => {
            Some(NumpyScalarType::Int64)
        }
        NumpyObject::Float(_) | NumpyObject::FloatArray(_) => {
            Some(NumpyScalarType::Float64)
        }
        NumpyObject::ComplexArray(_) => {
            Some(NumpyScalarType::Complex128)
        }
        NumpyObject::Str(_) => Some(NumpyScalarType::String),
        NumpyObject::Bool(_) => Some(NumpyScalarType::Bool),
        NumpyObject::Generic => default,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_obj2sctype() {
        assert_eq!(
            obj2sctype(NumpyObject::Int(42), None),
            Some(NumpyScalarType::Int64)
        );
        assert_eq!(
            obj2sctype(NumpyObject::IntArray(vec![1, 2, 3]), None),
            Some(NumpyScalarType::Int64)
        );
        assert_eq!(
            obj2sctype(NumpyObject::Float(3.14), None),
            Some(NumpyScalarType::Float64)
        );
        assert_eq!(
            obj2sctype(NumpyObject::FloatArray(vec![1.0, 2.0]), None),
            Some(NumpyScalarType::Float64)
        );
        assert_eq!(
            obj2sctype(
                NumpyObject::ComplexArray(vec![(0.0, 1.0), (1.0, 0.0)]),
                None
            ),
            Some(NumpyScalarType::Complex128)
        );
        assert_eq!(
            obj2sctype(NumpyObject::Str("hello".into()), None),
            Some(NumpyScalarType::String)
        );
        assert_eq!(
            obj2sctype(NumpyObject::Bool(true), None),
            Some(NumpyScalarType::Bool)
        );

        // Generic with a default
        assert_eq!(
            obj2sctype(NumpyObject::Generic, Some(NumpyScalarType::Float64)),
            Some(NumpyScalarType::Float64)
        );
        // Generic without a default
        assert_eq!(obj2sctype(NumpyObject::Generic, None), None);
    }
}